from pathlib import Path
import re

shop = Path('TehranSupermarket/shop.php')
cssp = Path('TehranSupermarket/assets/tehran-final-v16.css')
s = shop.read_text(encoding='utf-8')
css = cssp.read_text(encoding='utf-8')
# Inline CSS resolves URLs relative to shop.php rather than the assets directory.
css = css.replace("url('tehran-storefront-hq-v34.webp?", "url('assets/tehran-storefront-hq-v34.webp?")
css = css.replace('url("tehran-storefront-hq-v34.webp?', 'url("assets/tehran-storefront-hq-v34.webp?')

css = css.replace("url('tehran-storefront-v3.svg?v=20261027-ref17')", "url('assets/tehran-storefront-v3.svg?v=20261027-ref18')")
css = css.replace('url("tehran-storefront-v3.svg?v=20261027-ref17")', 'url("assets/tehran-storefront-v3.svg?v=20261027-ref18")')

mobile_b64 = ''''''

cleanup = f'''
/* tm-ref-mobile-exact-v19 */
#barcode-scan-fab,#tehran-ai-fab-v2,.tehran-ai-ping{{display:none!important;visibility:hidden!important;opacity:0!important;pointer-events:none!important}}
body{{visibility:visible!important;opacity:1!important}}
@media(max-width:800px){{
  .tm-ref-head-main{{grid-template-columns:42px 48px 1fr 42px!important;grid-template-areas:'account brand cart menu' 'search search search search'!important;gap:8px!important;padding:8px 10px!important}}
  .tm-ref-menu-mobile{{grid-area:menu!important}}
  .tm-ref-head-actions .cart{{grid-area:cart!important}}
  .tm-ref-brand{{grid-area:brand!important;justify-self:center!important;margin:0!important}}
  .tm-ref-head-actions .acct{{grid-area:account!important}}
  .tm-ref-brand-copy b{{font-size:17px!important}}
  .tm-ref-brand-copy small{{font-size:6.5px!important}}
  .tm-ref-brand-mark{{font-size:22px!important}}
  .tm-ref-hero{{background-image:url("data:image/jpeg;base64,{mobile_b64}")!important;background-size:cover!important;background-position:center!important;min-height:212px!important;height:212px!important;border-radius:0!important}}
  .tm-ref-hero:before{{display:none!important}}
  .tm-ref-hero-inner{{position:relative!important;display:block!important;min-height:212px!important;height:212px!important;padding:0!important}}
  .tm-ref-hero-copy{{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;pointer-events:none!important}}
  .tm-ref-hero-copy h1,.tm-ref-hero-copy p,.tm-ref-hero-features,.tm-ref-dots{{display:none!important}}
  .tm-ref-cta{{position:absolute!important;left:34px!important;bottom:22px!important;width:112px!important;height:36px!important;padding:0!important;opacity:0!important;pointer-events:auto!important}}
  .tm-ref-trust-wrap{{margin:-1px 10px 12px!important;padding:0!important}}
  .tm-ref-trust{{border-radius:0 0 16px 16px!important;box-shadow:0 8px 18px #00000012!important}}
  .tm-ref-section{{margin-top:14px!important}}
  .tm-ref-promos{{gap:8px!important;margin-top:10px!important}}
}}
'''
inline = '<style id="tm-ref-inline-v18">\n' + css + '\n' + cleanup + '\n</style>'

s = re.sub(r'<style id="tm-ref-inline-v\d+">.*?</style>', '', s, flags=re.S)
s = re.sub(r'<link rel="stylesheet" href="assets/tehran-final-v16\.css\?v=[^"\']+">', '', s)
s = re.sub(r'<link href="assets/tehran-final-v16\.css\?v=[^"\']+" rel="stylesheet">', '', s)
if '</head>' not in s:
    raise SystemExit('head marker missing')
s = s.replace('</head>', inline + '</head>', 1)
shop.write_text(s, encoding='utf-8')
